import { Controller, HttpException, isSafeRedirectUrl, ValidationException } from '@guren/core'
import { NewsletterSubscription } from '../../Models/NewsletterSubscription.js'

export default class NewsletterController extends Controller {
  async subscribe(): Promise<Response> {
    const { body } = this.validated('newsletter.subscribe')

    if (await NewsletterSubscription.first({ email: body.email })) {
      throw ValidationException.withMessages({ email: 'This email is already subscribed.' })
    }

    await NewsletterSubscription.create({ email: body.email, token: crypto.randomUUID() + crypto.randomUUID() })
    return this.redirect(this.backUrl())
  }

  async confirm(): Promise<Response> {
    const { params } = this.validated('newsletter.confirm')
    const subscription = await NewsletterSubscription.first({ token: params.token })
    if (!subscription) throw HttpException.notFound()

    await NewsletterSubscription.update({ id: subscription.id }, { confirmedAt: new Date().toISOString() })
    return this.redirect('/')
  }

  async unsubscribe(): Promise<Response> {
    const { body } = this.validated('newsletter.unsubscribe')
    await NewsletterSubscription.delete({ email: body.email })
    return this.redirect(this.backUrl())
  }

  private backUrl(): string {
    const referer = this.ctx.req.header('referer')
    return referer && isSafeRedirectUrl(referer, this.ctx.req.url) ? referer : '/'
  }
}
EOF
cat > modules/newsletter/routes.ts <<'EOF'
import type { Router } from '@guren/core'
import NewsletterController from './app/Http/Controllers/NewsletterController.js'
import { ConfirmParamSchema, NewsletterEmailSchema } from './app/Http/Validators/NewsletterValidator.js'

export function registerNewsletterRoutes(router: Router): void {
  router.post('/subscribe', { name: 'newsletter.subscribe', body: NewsletterEmailSchema }, [NewsletterController, 'subscribe'])
  router.get('/confirm/:token', { name: 'newsletter.confirm', params: ConfirmParamSchema }, [NewsletterController, 'confirm'])
  router.post('/unsubscribe', { name: 'newsletter.unsubscribe', body: NewsletterEmailSchema }, [NewsletterController, 'unsubscribe'])
}
EOF
